pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(address logAddr) public {
        vm.assume(logAddr != address(0) && logAddr != address(c));
        c.Initialized();
        bool ok = true;
        try c.SetLogFile(logAddr) { ok = true; } catch { ok = false; }
        assertTrue(!ok);
    }
}
